tool_calls.arguments:
{"command": "kubectl -n default patch deploy app --type=merge -p '{
  "spec": {
    "template": {
      "spec": {
        "affinity": {
          "podAntiAffinity": {
            "requiredDuringSchedulingIgnoredDuringExecution": null,
            "preferredDuringSchedulingIgnoredDuringExecution": [
              {
                "weight": 100,
                "podAffinityTerm": {
                  "labelSelector": {"matchLabels": {"app": "app"}},
                  "topologyKey": "kubernetes.io/hostname"
                }
              }
            ]
          }
        }
      }
    }
  }
}' 2>&1; echo "=== resulting affinity ==="; kubectl -n default get deploy app -o jsonpath='{.spec.template.spec.affinity}{"\n"}'"}

